import{_ as e,o as s,c as n,a1 as o}from"./chunks/framework.Ccs17H5l.js";const h=JSON.parse('{"title":"Commands and Export","description":"","frontmatter":{},"headers":[],"relativePath":"guide/commands.md","filePath":"guide/commands.md"}'),t={name:"guide/commands.md"};function l(d,a,r,i,c,p){return s(),n("div",null,[...a[0]||(a[0]=[o('<h1 id="commands-and-export" tabindex="-1">Commands and Export <a class="header-anchor" href="#commands-and-export" aria-label="Permalink to &quot;Commands and Export&quot;">​</a></h1><h2 id="building-and-exporting" tabindex="-1">Building and Exporting <a class="header-anchor" href="#building-and-exporting" aria-label="Permalink to &quot;Building and Exporting&quot;">​</a></h2><p>Running <code>just build</code> or <code>just export</code> both compile your project. The difference is that <code>just export</code> also packages the output as a <code>.nwa</code> file — which is simply the compiled binary renamed and placed in a dedicated folder for easy distribution. Use <code>just export</code> when you want a file to install on a calculator or share with others.</p><h2 id="command-reference" tabindex="-1">Command Reference <a class="header-anchor" href="#command-reference" aria-label="Permalink to &quot;Command Reference&quot;">​</a></h2><h3 id="build-run-and-export" tabindex="-1">Build, Run and Export <a class="header-anchor" href="#build-run-and-export" aria-label="Permalink to &quot;Build, Run and Export&quot;">​</a></h3><h4 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h4><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">just</span><span style="color:#CE9178;"> build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h4 id="run-the-simulator" tabindex="-1">Run the simulator <a class="header-anchor" href="#run-the-simulator" aria-label="Permalink to &quot;Run the simulator&quot;">​</a></h4><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">just</span><span style="color:#CE9178;"> sim</span><span style="color:#CE9178;"> {number_of_cores}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>See the <a href="./simulator.html">Simulator</a> page for details.</p><h4 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h4><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">just</span><span style="color:#CE9178;"> export</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Generates the <code>.nwa</code> file in the <code>build/</code> folder.</p><div class="info custom-block github-alert"><p class="custom-block-title">INFO</p><p>The output folder name may change in future updates.</p></div><h3 id="cleanup" tabindex="-1">Cleanup <a class="header-anchor" href="#cleanup" aria-label="Permalink to &quot;Cleanup&quot;">​</a></h3><h4 id="clean-project-files" tabindex="-1">Clean project files <a class="header-anchor" href="#clean-project-files" aria-label="Permalink to &quot;Clean project files&quot;">​</a></h4><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">just</span><span style="color:#CE9178;"> clean</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Deletes the compiled output of your application (<code>target/</code> and <code>build/</code> folders).</p><h4 id="full-reset" tabindex="-1">Full reset <a class="header-anchor" href="#full-reset" aria-label="Permalink to &quot;Full reset&quot;">​</a></h4><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">just</span><span style="color:#CE9178;"> clear</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Same as <code>just clean</code>, but also removes the compiled simulator files.</p><h3 id="configuration-and-maintenance" tabindex="-1">Configuration and Maintenance <a class="header-anchor" href="#configuration-and-maintenance" aria-label="Permalink to &quot;Configuration and Maintenance&quot;">​</a></h3><h4 id="download-the-compilation-target" tabindex="-1">Download the compilation target <a class="header-anchor" href="#download-the-compilation-target" aria-label="Permalink to &quot;Download the compilation target&quot;">​</a></h4><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">just</span><span style="color:#CE9178;"> target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Manually downloads the required compilation target. Normally done automatically on first build.</p><h4 id="update-local-tools" tabindex="-1">Update local tools <a class="header-anchor" href="#update-local-tools" aria-label="Permalink to &quot;Update local tools&quot;">​</a></h4><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki dark-plus vp-code" tabindex="0"><code><span class="line"><span style="color:#DCDCAA;">./update.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Updates project scripts and tooling (<code>docker.sh</code>, <code>update.sh</code>, <code>justfile</code>, etc.).</p><h3 id="internal-and-deprecated-commands" tabindex="-1">Internal and Deprecated Commands <a class="header-anchor" href="#internal-and-deprecated-commands" aria-label="Permalink to &quot;Internal and Deprecated Commands&quot;">​</a></h3><p>These are used by internal scripts or for specific test cases. <strong>No need to run them manually.</strong></p><h4 id="just-check-deprecated" tabindex="-1"><code>just check</code> <em>(deprecated)</em> <a class="header-anchor" href="#just-check-deprecated" aria-label="Permalink to &quot;`just check` *(deprecated)*&quot;">​</a></h4><p>Identical to <code>just build</code>. Use <code>just build</code> instead.</p><h4 id="just-build-simulator" tabindex="-1"><code>just build_simulator</code> <a class="header-anchor" href="#just-build-simulator" aria-label="Permalink to &quot;`just build_simulator`&quot;">​</a></h4><p>Compiles the app for the simulator without launching it. Used internally to verify simulator compatibility. Use <code>just sim</code> instead.</p>',34)])])}const m=e(t,[["render",l]]);export{h as __pageData,m as default};
